package main

import (
	"bufio"
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"log/slog"
	"net"
	"net/http"
	"sync"
	"time"
)

const requestIDHeader = "X-Request-ID"

// requestIDContextKey keeps request IDs separate from caller-controlled context values.
type requestIDContextKey struct{}

// requestID returns only an ID generated by observeRequests, never a caller-supplied header.
func requestID(r *http.Request) string {
	if r == nil {
		return ""
	}
	id, _ := r.Context().Value(requestIDContextKey{}).(string)
	return id
}

func generateRequestID() (string, error) {
	var id [16]byte
	if _, err := rand.Read(id[:]); err != nil {
		return "", err
	}
	return hex.EncodeToString(id[:]), nil
}

// observeRequests logs only safe request metadata. Disabled mode deliberately returns
// next unchanged, without adding a context value or touching either header map.
func observeRequests(enabled bool, next http.Handler) http.Handler {
	if !enabled {
		return next
	}

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		started := time.Now()
		logger := slog.Default()
		observer := &requestObservation{logger: logger, method: r.Method, requestID: ""}
		wrapped := newObservedResponseWriter(w, observer)

		id, err := generateRequestID()
		if err != nil {
			// Without entropy, fail closed rather than falling back to an untrusted or
			// predictable request identifier.
			http.Error(wrapped, http.StatusText(http.StatusInternalServerError), http.StatusInternalServerError)
			observer.finish(false, r, started)
			return
		}

		observer.requestID = id
		wrapped.Header().Set(requestIDHeader, id)
		request := r.Clone(context.WithValue(r.Context(), requestIDContextKey{}, id))
		request.Header = r.Header.Clone()
		if request.Header == nil {
			request.Header = make(http.Header)
		}
		request.Header.Set(requestIDHeader, id)

		returned := false
		defer func() {
			wrapped.Header().Set(requestIDHeader, id)
			observer.finish(returned, request, started)
		}()
		next.ServeHTTP(wrapped, request)
		returned = true
	})
}

type requestObservation struct {
	mu         sync.Mutex
	logger     *slog.Logger
	method     string
	requestID  string
	status     int
	statusSet  bool
	writeError bool
	hijacked   bool
}

func (o *requestObservation) recordStatus(status int) {
	o.mu.Lock()
	if !o.statusSet {
		o.status = status
		o.statusSet = true
	}
	o.mu.Unlock()
}

func (o *requestObservation) recordImplicitOK() {
	o.recordStatus(http.StatusOK)
}

func (o *requestObservation) recordWriteError() {
	o.mu.Lock()
	o.writeError = true
	o.mu.Unlock()
}

func (o *requestObservation) recordHijack() {
	o.mu.Lock()
	o.hijacked = true
	if !o.statusSet {
		o.status = http.StatusSwitchingProtocols
		o.statusSet = true
	}
	o.mu.Unlock()
}

func (o *requestObservation) finish(returned bool, r *http.Request, started time.Time) {
	o.mu.Lock()
	status := o.status
	if !o.statusSet && returned {
		// net/http commits an implicit 200 when a handler returns without writing.
		status = http.StatusOK
	}
	writeError := o.writeError
	hijacked := o.hijacked
	o.mu.Unlock()

	completed := returned && !writeError
	if completed && !hijacked && r.Context().Err() != nil {
		completed = false
	}

	// This outer wrapper observes the origin transport, not forwarded metadata
	// resolved in an inner request clone.
	scheme := "http"
	if r.TLS != nil {
		scheme = "https"
	}
	o.logger.Info("http request completed",
		"request_id", o.requestID,
		"method", o.method,
		"status", status,
		"duration", time.Since(started).Round(time.Microsecond),
		"origin_scheme", scheme,
		"completed", completed,
	)
}

type observedResponseWriter struct {
	http.ResponseWriter
	observer *requestObservation
}

func newObservedResponseWriter(w http.ResponseWriter, observer *requestObservation) http.ResponseWriter {
	base := &observedResponseWriter{ResponseWriter: w, observer: observer}
	flusher, hasFlusher := w.(http.Flusher)
	hasHijacker := supportsHijack(w)
	switch {
	case hasFlusher && hasHijacker:
		return observedFlushHijackWriter{observedResponseWriter: base, flusher: flusher}
	case hasFlusher:
		return observedFlushWriter{observedResponseWriter: base, flusher: flusher}
	case hasHijacker:
		return observedHijackWriter{observedResponseWriter: base}
	default:
		return base
	}
}

func supportsHijack(w http.ResponseWriter) bool {
	for range 100 {
		if _, ok := w.(http.Hijacker); ok {
			return true
		}
		unwrapper, ok := w.(interface{ Unwrap() http.ResponseWriter })
		if !ok {
			return false
		}
		w = unwrapper.Unwrap()
		if w == nil {
			return false
		}
	}
	return false
}

func (w *observedResponseWriter) FlushError() error {
	w.setRequestIDHeader()
	err := http.NewResponseController(w.ResponseWriter).Flush()
	if err == nil {
		w.observer.recordImplicitOK()
	} else if !errors.Is(err, http.ErrNotSupported) {
		w.observer.recordImplicitOK()
		w.observer.recordWriteError()
	}
	return err
}
func (w *observedResponseWriter) Unwrap() http.ResponseWriter {
	return w.ResponseWriter
}

func (w *observedResponseWriter) setRequestIDHeader() {
	if w.observer.requestID != "" {
		w.Header().Set(requestIDHeader, w.observer.requestID)
	}
}

func (w *observedResponseWriter) WriteHeader(status int) {
	w.setRequestIDHeader()
	w.ResponseWriter.WriteHeader(status)
	if status == http.StatusSwitchingProtocols || status >= 200 {
		w.observer.recordStatus(status)
	}
}

func (w *observedResponseWriter) Write(p []byte) (int, error) {
	w.setRequestIDHeader()
	w.observer.recordImplicitOK()
	n, err := w.ResponseWriter.Write(p)
	if err != nil {
		w.observer.recordWriteError()
	}
	return n, err
}

func (w *observedResponseWriter) flush(flusher http.Flusher) {
	w.setRequestIDHeader()
	w.observer.recordImplicitOK()
	flusher.Flush()
}

func (w *observedResponseWriter) hijack() (net.Conn, *bufio.ReadWriter, error) {
	w.setRequestIDHeader()
	conn, rw, err := http.NewResponseController(w.ResponseWriter).Hijack()
	if err == nil {
		w.observer.recordHijack()
	}
	return conn, rw, err
}

// These capability-specific wrappers avoid advertising Flush or Hijack when the
// underlying writer does not support it; Unwrap remains available to ResponseController.
type observedFlushWriter struct {
	*observedResponseWriter
	flusher http.Flusher
}

func (w observedFlushWriter) Flush() { w.observedResponseWriter.flush(w.flusher) }

type observedHijackWriter struct {
	*observedResponseWriter
}

func (w observedHijackWriter) Hijack() (net.Conn, *bufio.ReadWriter, error) {
	return w.observedResponseWriter.hijack()
}

type observedFlushHijackWriter struct {
	*observedResponseWriter
	flusher http.Flusher
}

func (w observedFlushHijackWriter) Flush() { w.observedResponseWriter.flush(w.flusher) }
func (w observedFlushHijackWriter) Hijack() (net.Conn, *bufio.ReadWriter, error) {
	return w.observedResponseWriter.hijack()
}
